var r = {
	   "z": 0,
    "s": 0,
    "co": 0,
    "urls": [],
    "sourl": "https://www.alicesw.com"
};

try {
    let v = JSON.parse(source.getVariable());
    if (v === null && typeof v !== 'object' && Array.isArray(v)) {
        source.setVariable(JSON.stringify(r, null, "\t"));
        java.toast('已初始化，使用默认站源');
    }
} catch (err) {
    java.log(err.message);
    source.setVariable(JSON.stringify(r, null, "\t"));
    java.toast('已初始化，使用默认站源');
}

var sgv = JSON.parse(source.getVariable());
var sg = source.get("list");
var ul = GetUL();

function reg() {
    java.startBrowser(`${ul}/user/user/reg.html`, "注册账号");
}

function Comment() {
    let sgvo = sgv.co;
    sgv.co = sgv.co ? 0 : 1;
    source.setVariable(JSON.stringify(sgv, null, "\t"));
    java.toast(`\n评论区\n【${["开启", "禁用"][sgvo]} → ${["开启", "禁用"][sgv.co]}】`);
}

function login() {
    Login();
}

function Tgch(o) {
    const sort = ["默认", "更新时间", "人气", "字数"];
    const one_ = sgv.s;
    const msg = (sgv.s = o, source.setVariable(JSON.stringify(sgv, null, "\t")), `排序方式\n【${sort[one_]}→${sort[o]}】`);
    java.toast("\n" + msg);
}

function Geturls() {
    sgv.urls.length = 0;
    try {
        const res = org.jsoup.Jsoup.parse(java.get('https://xn--vcsx64d.asw4.cc/', {}).body()).select('.container a');
        const url1 = java.base64Decode(res[0].attr('href').match(/['"](.*?)['"]/)[1]);
        sgv.urls.push(String(url1).replace(/\/?$/, ""));
        const url2 = java.base64Decode(res[1].attr('href').match(/['"](.*?)['"]/)[1]);
        let src = java.get(java.connect(url2).url(), {}).body();
        src = java.get(org.jsoup.Jsoup.parse(src).select('#redirectButton').attr('href'), {}).body();
        const seen = new Set();
        for (let match of src.matchAll(/u\d+\s*=\s*r\(["'](.*?)["']\)/g)) {
            if (!seen.has(match[1])) {
                sgv.urls.push(match[1].split('').reverse().join(''));
                seen.add(match[1]);
            }
        }
        source.setVariable(JSON.stringify(sgv, null, "\t"));

        if (sgv.urls.length >= 2) {
            java.toast(`获取成功，共获取到${sgv.urls.length}个站源\n┎┅┅┅┅┅┅┅┅┅┅┅┅┅┅┅┒\n${sgv.urls.join('\n')}\n┖┅┅┅┅┅┅┅┅┅┅┅┅┅┅┅┚`);
        } else {
            java.toast('获取失败，请重试或检查网络状况');
        }
    } catch (e) {
        java.log(e);
        java.toast('\n未知错误，请检查网络或更新阅读版本！');
    }
}

function Puturl(e) {
    if (!sgv.urls.length) return java.toast('\n当前没有站源，请获取后选择');
    if (e + 1 > sgv.urls.length) return java.toast(`暂无站源${e+1}`);

    try {
        const stime = Date.now();
        java.get(sgv.urls[e], {});
        const speedtime = (Date.now() - stime) / 1000;

        sgv.sourl = sgv.urls[e];
        sgv?.booklist?.forEach(item => {
            item.img = item.img.replace(/https?:\/\/[^\/]+/, sgv.urls[e]);
            item.url = item.url.replace(/https?:\/\/[^\/]+/, sgv.urls[e]);
        });
        source.setVariable(JSON.stringify(sgv, null, "\t"));

        // 切换接口保持登录状态
        const Cookie = cookie.getCookie(sgv.urls[e]);
        if (!/lf_user_auth/.test(Cookie) && source.getLoginHeader()) {
            cookie.setCookie(sgv.urls[e], source.getLoginHeaderMap().get('Cookie'));
        }
        java.toast(`站源已设置为【站源${e + 1}】：\n${sgv.urls[e]}\n♦解析用时${speedtime}秒♦`);
    } catch (err) {
        java.log(err.message);
        java.toast(`\n【站源${e+1}：${sgv.urls[e]}】\n已失效，请检查网络状况或切换其他站源`);
    }
}

function Login() {
    const na = result['用户名/邮箱'];
    const pa = result['密码'];
    if (na && pa && loginByApi(na, pa)) return;
    loginByBrowser();
}

// 接口直登：先取一次验证码页把会话钉住，再让用户输码，避免"看到的码"和"提交的会话"不是同一个
function loginByApi(na, pa) {
    const verifyUrl = `${ul}/user/user/verify.html`;
    try {
        cookie.removeCookie(ul);
        const vres = java.get(verifyUrl, {});
        // 站点返回的头名是 Set-Cookie（单数）；旧代码写成 set-cookies，永远取不到
        let sess = '';
        try { sess = vres.header('Set-Cookie') || ''; } catch (e) { sess = ''; }
        let m = /PHPSESSID=([^;,\s]+)/i.exec(sess);
        if (!m) m = /PHPSESSID=([^;\s]+)/i.exec(cookie.getCookie(ul) || '');
        if (m) cookie.setCookie(ul, `PHPSESSID=${m[1]}`);
        const code = java.getVerificationCode(verifyUrl);
        const response = java.post(
            `${ul}/user/user/login.html`,
            `username=${encodeURIComponent(na)}&password=${encodeURIComponent(pa)}&code=${encodeURIComponent(code || '')}`,
            { 'x-requested-with': 'XMLHttpRequest', 'Referer': `${ul}/user/user/login.html` }
        );
        let msg = response.body();
        try { msg = JSON.parse(response.body()).msg || msg; } catch (e) { msg = response.body(); }
        const jar = cookie.getCookie(ul) || '';
        let ck = cookie.mapToCookie(response.cookies()) || '';
        if (!/lf_user_auth/.test(ck) && /lf_user_auth/.test(jar)) ck = jar;
        if (/lf_user_auth/.test(ck)) {
            saveLogin(ck);
            java.toast(`登录成功${msg ? '：' + msg : ''}`);
            return true;
        }
        java.toast(msg || '登录失败');
    } catch (e) {
        java.log(e);
    }
    return false;
}

// 浏览器登录：在内置浏览器里完成（验证码、风控都在真实页面里走），退出浏览器时应用会把 cookie 同步回书源
function loginByBrowser() {
    java.startBrowserAwait(`${ul}/user/user/login.html`, '登录');
    const ck = cookie.getCookie(ul) || '';
    if (!/lf_user_auth/.test(ck)) {
        java.toast('未检测到登录 cookie，请在内置浏览器里完成登录后再点「登录」');
        return false;
    }
    saveLogin(ck);
    java.toast('登录成功');
    return true;
}

function saveLogin(ck) {
    source.putLoginHeader(JSON.stringify({ 'Cookie': ck }));
    try { cookie.setWebCookie(ul, ck); } catch (e) { java.log(e); }
}

function out() {
    source.removeLoginHeader();
    cookie.removeCookie(ul);
    try { cookie.setWebCookie(ul, ''); } catch (e) { java.log(e); }
