source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	bd=[["男频",[["留存","6"],["好评","3"],["人气","1"],["热评","5"]]],
["女频",[["留存","12"],["好评","9"],["人气","7"],["热评","11"]]]];
bd.map([title,list]=>{			
	Params = "BD";
		push(title, null, 1, 1);
	   list.map([title,cid]=>{ 
	   		eval(String(source.bookSourceComment));
	   	url= `https://fapi.fanxxs.com/2/v8/top3/list.api?sign=${sign}&app=FXBook&vs=7.1.2&uuid=${uuid}&_t=${time}&app=FXBook&pbv=v1.0.28&channel=fx0001&os=Android,`+ JSON.stringify(option).replace(/start=0/,'start={{(page-1)*30}\}');  
				push(title, url, 1, 0.4); 
				});
	});
		fl_url="https://fapi.fanxxs.com/v8/cate3/list.api?nsc=0&nci=1&app=FXBook&vs=7.1.2&uuid={{java.randomUUID().toUpperCase()}}&_t={{Math.round(new Date()/1000)}}&app=FXBook&pbv=v1.0.28&channel=fx0001&os=Android";
D=JSON.parse(java.ajax(fl_url)).data;

 [D[0],D[1]].map(Data=>{
 	Params = JSON.stringify(Data);
	push(Data.groupname, null, 1, 1);
Data.cate.map(($,index)=>{
      title=$.name;
     	cid=$.cid;
     	eval(String(source.bookSourceComment));
	url= `https://fapi.fanxxs.com/2/v8/book3/filter.api?app=FXBook&sign=${sign}&ml=10X&mf=XIAOMI&vs=7.1.2&uuid=${uuid}&_t=${time}&app=FXBook&pbv=v1.0.28&channel=fx0001&os=Android,`+ JSON.stringify(option).replace(/start=0/,'start={{(page-1)*30}\}');
 		if(index+1 <= Data.cate.length - Data.cate.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
        });
      });
JSON.stringify(sort);

